import json

def build_request(method, url, headers=None, json_body=None):
    hdrs = dict(headers or {})
    body = None
    if json_body is not None:
        body = json.dumps(json_body)
        hdrs.setdefault('Content-Type', 'application/json')
    return {'method': method.upper(), 'url': url, 'headers': hdrs, 'body': body}
